-- ========== 预算预测分析模块 - 表结构 ==========

-- 1. 预算预测分析表（重建，兼容已有测试数据列 + 前端所需列）
-- DROP TABLE IF EXISTS REDACTED.TBL_BUDGET_FORECAST_ANALYSIS;
CREATE TABLE IF NOT EXISTS "REDACTED"."TBL_BUDGET_FORECAST_ANALYSIS" (
    "ID"                  VARCHAR2(64) NOT NULL,
    "ANALYSIS_CODE"       VARCHAR2(100),
    "ANALYSIS_NAME"       VARCHAR2(200),
    "BUDGET_ID"           VARCHAR2(64),
    "BUDGET_YEAR"         INTEGER,
    "ORGANIZATION_ID"     VARCHAR2(64),
    "ORGANIZATION_NAME"   VARCHAR2(200),
    "ACCOUNT_ID"          VARCHAR2(64),
    "ACCOUNT_NAME"        VARCHAR2(200),
    "FORECAST_TYPE"       VARCHAR2(50),
    "FORECAST_METHOD"     VARCHAR2(50),
    "FORECAST_MODEL_NAME" VARCHAR2(200),
    "FORECAST_PERIOD"     VARCHAR2(50),
    "FORECAST_DATE"       VARCHAR2(20),
    "FORECAST_AMOUNT"     NUMBER(20,2),
    "ACTUAL_AMOUNT"       NUMBER(20,2),
    "HISTORICAL_VALUE"    NUMBER(20,2),
    "UPPER_BOUND"         NUMBER(20,2),
    "LOWER_BOUND"         NUMBER(20,2),
    "CONFIDENCE_LEVEL"    NUMBER(10,2),
    "ACCURACY_RATE"       NUMBER(10,2),
    "TREND"               VARCHAR2(20),
    "FORECAST_GRANULARITY" VARCHAR2(20),
    "CONFIDENCE_INTERVAL" VARCHAR2(10),
    "ANALYSIS_STATUS"     VARCHAR2(50) DEFAULT 'DRAFT',
    "ANALYZED_BY"         VARCHAR2(100),
    "REMARK"              VARCHAR2(500),
    "CREATE_BY"           VARCHAR2(100),
    "CREATE_TIME"         TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"           VARCHAR2(100),
    "UPDATE_TIME"         TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"            INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_FORECAST_ANALYSIS IS '预算预测分析表';

-- 2. 预测模型信息表
CREATE TABLE IF NOT EXISTS "REDACTED"."TBL_BUDGET_FORECAST_MODEL" (
    "ID"                VARCHAR2(64) NOT NULL,
    "MODEL_CODE"        VARCHAR2(100),
    "MODEL_NAME"        VARCHAR2(200),
    "MODEL_TYPE"        VARCHAR2(50),
    "DESCRIPTION"       VARCHAR2(500),
    "TRAINING_DATA_DESC" VARCHAR2(200),
    "ACCURACY"          NUMBER(10,2),
    "R_SQUARED"         NUMBER(10,4),
    "RMSE"              NUMBER(20,4),
    "MAE"               NUMBER(20,4),
    "MAPE"              NUMBER(10,4),
    "IS_ACTIVE"         INTEGER DEFAULT 0,
    "LAST_TRAIN_TIME"   TIMESTAMP(6),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_FORECAST_MODEL IS '预测模型信息表';

